#!/usr/bin/env node
'use strict';
/**
 * CP83 immutable-source verification, not a quality/deployment/science claim.
 * Dynamic reports generated by CP82 tests are excluded explicitly in the
 * release manifest, not silently re-hashed as if they were immutable evidence.
 */
const fs=require('node:fs');
const path=require('node:path');
const crypto=require('node:crypto');
const ROOT=path.resolve(__dirname,'..');
const MANIFEST='CP83_SOURCE_MANIFEST.json';
const FORBIDDEN=[
  'src/page/main/RolePage.tsx',
  'src/components/common/StudentLinkManager.tsx',
  'src/components/common/SharedReportPanel.tsx',
  'src/audit_dataset.py',
  'src/baseline_next_term.py',
];
function safeRel(rel){
  return typeof rel==='string' && rel.length>0 && !path.isAbsolute(rel) &&
   !rel.includes('\\') && !rel.includes('\0') &&
   rel.split('/').every(part=>part!=='' && part!=='.' && part!=='..');
}
function verifyRelease(root=ROOT,manifestFile=MANIFEST){
  const errors=[];
  let manifest;
  try{manifest=JSON.parse(fs.readFileSync(path.join(root,manifestFile),'utf8'));}
  catch(e){return {ok:false,errors:['MANIFEST_ERROR '+e.message],count:0};}
  if(manifest.schema!=='cla.cp83.immutable-source.v1'||!Array.isArray(manifest.files)||!Array.isArray(manifest.mutableOutputs))
    return {ok:false,errors:['INVALID_MANIFEST_SCHEMA'],count:0};
  const paths=new Set();
  const mutable=new Set();
  for(const rel of manifest.mutableOutputs){
    if(!safeRel(rel)||mutable.has(rel))errors.push('INVALID_MUTABLE_OUTPUT '+String(rel));
    mutable.add(rel);
  }
  for(const entry of manifest.files){
    if(!entry || !safeRel(entry.path) || !/^[a-f0-9]{64}$/.test(entry.sha256||'') || paths.has(entry.path) || mutable.has(entry.path)){
      errors.push('INVALID_MANIFEST_ENTRY '+String(entry?.path));continue;
    }
    paths.add(entry.path);
    const f=path.join(root,entry.path);
    try{
      const st=fs.lstatSync(f);
      if(!st.isFile()) {errors.push('NOT_REGULAR_FILE '+entry.path);continue;}
      const sum=crypto.createHash('sha256').update(fs.readFileSync(f)).digest('hex');
      if(sum!==entry.sha256)errors.push('CHANGED '+entry.path);
    }catch(e){errors.push('MISSING '+entry.path);}
  }
  for(const rel of FORBIDDEN){
    if(fs.existsSync(path.join(root,rel)))errors.push('RETIRED_OR_MISPLACED '+rel);
  }
  return {ok:errors.length===0,errors,count:paths.size,mutableCount:mutable.size};
}
if(require.main===module){
  const result=verifyRelease();
  if(!result.ok){
    console.error('CLA CP83 IMMUTABLE SOURCE FAIL: '+result.errors.length+' discrepancies');
    result.errors.slice(0,25).forEach(e=>console.error(e));
    process.exitCode=1;
  }else{
    console.log('CLA CP83 IMMUTABLE SOURCE PASS: '+result.count+' files SHA-256 matched; '+result.mutableCount+' explicitly declared generated report paths excluded.');
    console.log('NOT proof of production security, external validation, or scientific effect.');
  }
}
module.exports={safeRel,verifyRelease,FORBIDDEN};
